-- Additive exam v2 foundation. Legacy exam/class/course tables remain untouched.
CREATE TABLE IF NOT EXISTS "exam_settings_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"version" integer NOT NULL DEFAULT 1,"status" text NOT NULL DEFAULT 'Draft',"current_step" integer NOT NULL DEFAULT 1,"feature_enabled" boolean NOT NULL DEFAULT false,"policy_status" text NOT NULL DEFAULT 'Pending',"rules" jsonb NOT NULL DEFAULT '{}'::jsonb,"completed_at" timestamptz,"completed_by" text REFERENCES "users"("id"),"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("current_step" BETWEEN 1 AND 5),CHECK ("status" IN ('Draft','Complete','Archived')),CHECK ("policy_status" IN ('Pending','Confirmed')));
CREATE UNIQUE INDEX IF NOT EXISTS "exam_settings_v2_school_version_uq" ON "exam_settings_v2"("school_id","version");
CREATE INDEX IF NOT EXISTS "exam_settings_v2_school_status_idx" ON "exam_settings_v2"("school_id","status");

CREATE TABLE IF NOT EXISTS "class_progressions_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"academic_year_id" text NOT NULL REFERENCES "academic_years"("id"),"class_id" text NOT NULL REFERENCES "classes"("id"),"progression_order" integer NOT NULL,"next_class_id" text REFERENCES "classes"("id"),"is_final" boolean NOT NULL DEFAULT false,"status" text NOT NULL DEFAULT 'Active',"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("progression_order">0),CHECK (("is_final" AND "next_class_id" IS NULL) OR NOT "is_final"));
CREATE UNIQUE INDEX IF NOT EXISTS "class_progressions_v2_year_class_uq" ON "class_progressions_v2"("academic_year_id","class_id");
CREATE UNIQUE INDEX IF NOT EXISTS "class_progressions_v2_year_order_uq" ON "class_progressions_v2"("academic_year_id","progression_order");
CREATE INDEX IF NOT EXISTS "class_progressions_v2_school_year_idx" ON "class_progressions_v2"("school_id","academic_year_id");

CREATE TABLE IF NOT EXISTS "academic_subjects_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"name" text NOT NULL,"normalized_name" text NOT NULL,"status" text NOT NULL DEFAULT 'Active',"legacy_source" jsonb NOT NULL DEFAULT '{}'::jsonb,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "academic_subjects_v2_school_name_uq" ON "academic_subjects_v2"("school_id","normalized_name");

CREATE TABLE IF NOT EXISTS "class_subject_offerings_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"academic_year_id" text NOT NULL REFERENCES "academic_years"("id"),"class_id" text NOT NULL REFERENCES "classes"("id"),"subject_id" text NOT NULL REFERENCES "academic_subjects_v2"("id"),"status" text NOT NULL DEFAULT 'Active',"effective_from" timestamptz NOT NULL,"effective_to" timestamptz,"source_version" integer NOT NULL DEFAULT 1,"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("effective_to" IS NULL OR "effective_to">"effective_from"));
CREATE UNIQUE INDEX IF NOT EXISTS "class_subject_offerings_v2_key_uq" ON "class_subject_offerings_v2"("academic_year_id","class_id","subject_id","source_version");
CREATE INDEX IF NOT EXISTS "class_subject_offerings_v2_lookup_idx" ON "class_subject_offerings_v2"("school_id","academic_year_id","class_id","subject_id");

CREATE TABLE IF NOT EXISTS "offering_teachers_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"offering_id" text NOT NULL REFERENCES "class_subject_offerings_v2"("id"),"teacher_id" text NOT NULL REFERENCES "users"("id"),"role" text NOT NULL DEFAULT 'Lead',"status" text NOT NULL DEFAULT 'Active',"effective_from" timestamptz NOT NULL,"effective_to" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("role" IN ('Lead','CoTeacher')),CHECK ("effective_to" IS NULL OR "effective_to">"effective_from"));
CREATE UNIQUE INDEX IF NOT EXISTS "offering_teachers_v2_key_uq" ON "offering_teachers_v2"("offering_id","teacher_id","effective_from");
CREATE INDEX IF NOT EXISTS "offering_teachers_v2_offering_idx" ON "offering_teachers_v2"("offering_id","status");

CREATE TABLE IF NOT EXISTS "exam_templates_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"family_id" text NOT NULL,"version" integer NOT NULL,"name" text NOT NULL,"category" text NOT NULL,"status" text NOT NULL DEFAULT 'Draft',"promotion_exam" boolean NOT NULL DEFAULT false,"re_exam_allowed" boolean NOT NULL DEFAULT false,"visibility" text NOT NULL DEFAULT 'PublishedOnly',"rules" jsonb NOT NULL DEFAULT '{}'::jsonb,"created_by" text NOT NULL REFERENCES "users"("id"),"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("version">0));
CREATE UNIQUE INDEX IF NOT EXISTS "exam_templates_v2_family_version_uq" ON "exam_templates_v2"("family_id","version");
CREATE INDEX IF NOT EXISTS "exam_templates_v2_school_status_idx" ON "exam_templates_v2"("school_id","status");

CREATE TABLE IF NOT EXISTS "exam_template_subjects_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"template_id" text NOT NULL REFERENCES "exam_templates_v2"("id"),"subject_id" text NOT NULL REFERENCES "academic_subjects_v2"("id"),"subject_order" integer NOT NULL,"max_mark" numeric(8,2) NOT NULL,"minimum_mark" numeric(8,2) NOT NULL,"required" boolean NOT NULL DEFAULT true,"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("subject_order">0),CHECK ("max_mark">0),CHECK ("minimum_mark">=0 AND "minimum_mark"<="max_mark"));
CREATE UNIQUE INDEX IF NOT EXISTS "exam_template_subjects_v2_template_subject_uq" ON "exam_template_subjects_v2"("template_id","subject_id");
CREATE UNIQUE INDEX IF NOT EXISTS "exam_template_subjects_v2_template_order_uq" ON "exam_template_subjects_v2"("template_id","subject_order");

CREATE TABLE IF NOT EXISTS "exam_sessions_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"academic_year_id" text NOT NULL REFERENCES "academic_years"("id"),"template_id" text NOT NULL REFERENCES "exam_templates_v2"("id"),"title" text NOT NULL,"term" text NOT NULL,"start_date" date NOT NULL,"end_date" date NOT NULL,"teacher_deadline" timestamptz NOT NULL,"publish_mode" text NOT NULL DEFAULT 'Manual',"status" text NOT NULL DEFAULT 'Draft',"rules_snapshot" jsonb NOT NULL,"source_snapshot" jsonb NOT NULL DEFAULT '{}'::jsonb,"parent_session_id" text,"idempotency_key" text NOT NULL,"request_hash" text NOT NULL,"created_by" text NOT NULL REFERENCES "users"("id"),"published_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("end_date">="start_date"),CHECK ("publish_mode" IN ('Manual')),CHECK ("status" IN ('Draft','Collecting','Published','Cancelled')));
CREATE UNIQUE INDEX IF NOT EXISTS "exam_sessions_v2_school_idempotency_uq" ON "exam_sessions_v2"("school_id","idempotency_key");
CREATE INDEX IF NOT EXISTS "exam_sessions_v2_school_year_status_idx" ON "exam_sessions_v2"("school_id","academic_year_id","status");

CREATE TABLE IF NOT EXISTS "exam_session_classes_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"session_id" text NOT NULL REFERENCES "exam_sessions_v2"("id"),"class_id" text NOT NULL REFERENCES "classes"("id"),"class_order" integer NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "exam_session_classes_v2_session_class_uq" ON "exam_session_classes_v2"("session_id","class_id");

CREATE TABLE IF NOT EXISTS "exam_assignments_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"session_id" text NOT NULL REFERENCES "exam_sessions_v2"("id"),"session_class_id" text NOT NULL REFERENCES "exam_session_classes_v2"("id"),"template_subject_id" text NOT NULL REFERENCES "exam_template_subjects_v2"("id"),"offering_id" text NOT NULL REFERENCES "class_subject_offerings_v2"("id"),"class_id" text NOT NULL REFERENCES "classes"("id"),"subject_id" text NOT NULL REFERENCES "academic_subjects_v2"("id"),"lead_teacher_id" text NOT NULL REFERENCES "users"("id"),"subject_name_snapshot" text NOT NULL,"max_mark" numeric(8,2) NOT NULL,"minimum_mark" numeric(8,2) NOT NULL,"deadline" timestamptz NOT NULL,"status" text NOT NULL DEFAULT 'Draft',"hard_locked" boolean NOT NULL DEFAULT false,"submitted_at" timestamptz,"late_seconds" integer,"reopened_at" timestamptz,"reopened_by" text REFERENCES "users"("id"),"reopen_reason" text,"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("max_mark">0),CHECK ("minimum_mark">=0 AND "minimum_mark"<="max_mark"),CHECK ("status" IN ('Draft','Submitted','Late','Reopened','NotApplicable')));
CREATE UNIQUE INDEX IF NOT EXISTS "exam_assignments_v2_session_class_subject_uq" ON "exam_assignments_v2"("session_id","class_id","template_subject_id");
CREATE INDEX IF NOT EXISTS "exam_assignments_v2_teacher_status_idx" ON "exam_assignments_v2"("lead_teacher_id","status");
CREATE INDEX IF NOT EXISTS "exam_assignments_v2_session_idx" ON "exam_assignments_v2"("session_id");

CREATE TABLE IF NOT EXISTS "exam_assignment_teachers_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"assignment_id" text NOT NULL REFERENCES "exam_assignments_v2"("id"),"teacher_id" text NOT NULL REFERENCES "users"("id"),"role" text NOT NULL,"source_teacher_link_id" text REFERENCES "offering_teachers_v2"("id"),"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "exam_assignment_teachers_v2_key_uq" ON "exam_assignment_teachers_v2"("assignment_id","teacher_id");

CREATE TABLE IF NOT EXISTS "exam_assignment_students_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"assignment_id" text NOT NULL REFERENCES "exam_assignments_v2"("id"),"student_id" text NOT NULL REFERENCES "students"("id"),"enrollment_id" text,"status" text NOT NULL DEFAULT 'Expected',"reason" text,"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("status" IN ('Expected','Withdrawn','Exempt')));
CREATE UNIQUE INDEX IF NOT EXISTS "exam_assignment_students_v2_key_uq" ON "exam_assignment_students_v2"("assignment_id","student_id");
CREATE INDEX IF NOT EXISTS "exam_assignment_students_v2_student_idx" ON "exam_assignment_students_v2"("student_id");

CREATE TABLE IF NOT EXISTS "exam_scores_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"assignment_student_id" text NOT NULL REFERENCES "exam_assignment_students_v2"("id"),"score" numeric(8,2),"mark_status" text NOT NULL DEFAULT 'Missing',"reason" text,"revision" integer NOT NULL DEFAULT 1,"updated_by" text NOT NULL REFERENCES "users"("id"),"updated_at" timestamptz NOT NULL DEFAULT now(),CHECK ("mark_status" IN ('Missing','Scored','Absent','Withdrawn','Exempt')),CHECK (("mark_status"='Scored' AND "score" IS NOT NULL) OR ("mark_status"<>'Scored' AND "score" IS NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS "exam_scores_v2_roster_uq" ON "exam_scores_v2"("assignment_student_id");

CREATE TABLE IF NOT EXISTS "exam_results_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"session_id" text NOT NULL REFERENCES "exam_sessions_v2"("id"),"student_id" text NOT NULL REFERENCES "students"("id"),"class_id" text NOT NULL REFERENCES "classes"("id"),"earned" numeric(12,2) NOT NULL,"possible" numeric(12,2) NOT NULL,"average" numeric(8,4) NOT NULL,"display_average" numeric(8,2) NOT NULL,"rank" integer NOT NULL,"outcome" text NOT NULL,"passed_subjects" integer NOT NULL,"failed_subjects" integer NOT NULL,"eligibility" jsonb NOT NULL DEFAULT '{}'::jsonb,"calculation_version" text NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "exam_results_v2_session_student_uq" ON "exam_results_v2"("session_id","student_id");
CREATE INDEX IF NOT EXISTS "exam_results_v2_student_idx" ON "exam_results_v2"("student_id");

CREATE TABLE IF NOT EXISTS "exam_result_subjects_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"result_id" text NOT NULL REFERENCES "exam_results_v2"("id"),"subject_id" text NOT NULL REFERENCES "academic_subjects_v2"("id"),"assignment_id" text NOT NULL REFERENCES "exam_assignments_v2"("id"),"earned" numeric(8,2) NOT NULL,"possible" numeric(8,2) NOT NULL,"minimum_mark" numeric(8,2) NOT NULL,"outcome" text NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "exam_result_subjects_v2_result_subject_uq" ON "exam_result_subjects_v2"("result_id","subject_id");

CREATE TABLE IF NOT EXISTS "exam_decisions_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"result_id" text NOT NULL REFERENCES "exam_results_v2"("id"),"student_id" text NOT NULL REFERENCES "students"("id"),"subject_id" text REFERENCES "academic_subjects_v2"("id"),"decision" text NOT NULL,"status" text NOT NULL DEFAULT 'Open',"reason" text NOT NULL,"parent_decision_id" text,"decided_by" text NOT NULL REFERENCES "users"("id"),"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("decision" IN ('Repeat','Re-exam','SpecialReview','NoChange','Correction')));
CREATE INDEX IF NOT EXISTS "exam_decisions_v2_result_status_idx" ON "exam_decisions_v2"("result_id","status");

CREATE TABLE IF NOT EXISTS "student_promotions_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"student_id" text NOT NULL REFERENCES "students"("id"),"source_result_id" text REFERENCES "exam_results_v2"("id"),"from_academic_year_id" text NOT NULL REFERENCES "academic_years"("id"),"to_academic_year_id" text NOT NULL REFERENCES "academic_years"("id"),"from_class_id" text NOT NULL REFERENCES "classes"("id"),"to_class_id" text REFERENCES "classes"("id"),"kind" text NOT NULL DEFAULT 'Promotion',"status" text NOT NULL DEFAULT 'Pending',"idempotency_key" text NOT NULL,"applied_at" timestamptz,"applied_by" text REFERENCES "users"("id"),"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("status" IN ('Pending','Applied','Cancelled')));
CREATE UNIQUE INDEX IF NOT EXISTS "student_promotions_v2_source_uq" ON "student_promotions_v2"("source_result_id") WHERE "source_result_id" IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "student_promotions_v2_school_idempotency_uq" ON "student_promotions_v2"("school_id","idempotency_key");
CREATE INDEX IF NOT EXISTS "student_promotions_v2_transition_idx" ON "student_promotions_v2"("to_academic_year_id","status");

CREATE TABLE IF NOT EXISTS "courses_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"academic_year_id" text NOT NULL REFERENCES "academic_years"("id"),"name" text NOT NULL,"description" text NOT NULL DEFAULT '',"start_date" date NOT NULL,"end_date" date NOT NULL,"capacity" integer NOT NULL,"fee" numeric(12,2) NOT NULL DEFAULT 0,"payment_type" text NOT NULL DEFAULT 'None',"target_class_id" text NOT NULL REFERENCES "classes"("id"),"status" text NOT NULL DEFAULT 'Draft',"rules" jsonb NOT NULL DEFAULT '{}'::jsonb,"created_by" text NOT NULL REFERENCES "users"("id"),"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("end_date">="start_date"),CHECK ("capacity">0),CHECK ("fee">=0),CHECK ("status" IN ('Draft','Open','Running','Completed','Cancelled')));
CREATE INDEX IF NOT EXISTS "courses_v2_school_year_status_idx" ON "courses_v2"("school_id","academic_year_id","status");
CREATE TABLE IF NOT EXISTS "course_classes_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"course_id" text NOT NULL REFERENCES "courses_v2"("id"),"class_id" text NOT NULL REFERENCES "classes"("id"),"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "course_classes_v2_key_uq" ON "course_classes_v2"("course_id","class_id");
CREATE TABLE IF NOT EXISTS "course_subjects_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"course_id" text NOT NULL REFERENCES "courses_v2"("id"),"subject_id" text NOT NULL REFERENCES "academic_subjects_v2"("id"),"teacher_id" text REFERENCES "users"("id"),"subject_order" integer NOT NULL,"rules" jsonb NOT NULL DEFAULT '{}'::jsonb,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "course_subjects_v2_key_uq" ON "course_subjects_v2"("course_id","subject_id");
CREATE TABLE IF NOT EXISTS "course_offers_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"course_id" text NOT NULL REFERENCES "courses_v2"("id"),"student_id" text NOT NULL REFERENCES "students"("id"),"source_result_id" text REFERENCES "exam_results_v2"("id"),"status" text NOT NULL DEFAULT 'Offered',"source" text NOT NULL,"reason" text,"expires_at" timestamptz,"responded_at" timestamptz,"responded_by" text REFERENCES "users"("id"),"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "course_offers_v2_course_student_uq" ON "course_offers_v2"("course_id","student_id");
CREATE TABLE IF NOT EXISTS "course_enrollments_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"course_id" text NOT NULL REFERENCES "courses_v2"("id"),"offer_id" text REFERENCES "course_offers_v2"("id"),"student_id" text NOT NULL REFERENCES "students"("id"),"source_class_id" text NOT NULL REFERENCES "classes"("id"),"normal_promotion_class_id" text REFERENCES "classes"("id"),"target_class_id" text NOT NULL REFERENCES "classes"("id"),"status" text NOT NULL DEFAULT 'Reserved',"seat_number" integer NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now(),CHECK ("seat_number">0));
CREATE UNIQUE INDEX IF NOT EXISTS "course_enrollments_v2_course_student_uq" ON "course_enrollments_v2"("course_id","student_id");
CREATE UNIQUE INDEX IF NOT EXISTS "course_enrollments_v2_course_seat_uq" ON "course_enrollments_v2"("course_id","seat_number");
CREATE TABLE IF NOT EXISTS "course_payments_v2" ("id" text PRIMARY KEY,"school_id" text NOT NULL REFERENCES "schools"("id"),"enrollment_id" text NOT NULL REFERENCES "course_enrollments_v2"("id"),"invoice_id" text,"status" text NOT NULL DEFAULT 'Pending',"required_amount" numeric(12,2) NOT NULL,"posted_amount" numeric(12,2) NOT NULL DEFAULT 0,"source" text NOT NULL DEFAULT 'Finance',"updated_at" timestamptz NOT NULL DEFAULT now(),CHECK ("required_amount">=0),CHECK ("posted_amount">=0 AND "posted_amount"<="required_amount"));
CREATE UNIQUE INDEX IF NOT EXISTS "course_payments_v2_enrollment_uq" ON "course_payments_v2"("enrollment_id");
